const hhmm = (ts, tz) => { const d = new Date(ts + (tz == null ? -new Date().getTimezoneOffset() : tz * 60) * 60e3); return pad(d.getUTCHours()) + ":" + pad(d.getUTCMinutes()); };
const lateTxt = min => min >= 60 ? T(Math.round(min / 60) + " 小时", Math.round(min / 60) + " h") : T(min + " 分钟", min + " min");
function moState(){ const t = moTs(O), now = Date.now(); return now < t ? "wait" : now - t < 120e3 ? "live" : "past"; }
