  let h = `<div class="ha-ln ak-say"${LA(l)} data-aksay="${esc(strip(a.t))}" data-akl="${esc(l)}" data-akns="${NS}" data-akspk="${esc(id)}">${html}${A().mutedFr(a.t, {l, ns: NS, spk: id}) ? "" : `<i class="ak-ear">🔊</i>`}${a.p ? `<span class="ak-py" dir="ltr">${esc(a.p)}</span>` : ""}</div>`;
  if (mine && a.nob) h += `<div class="ha-nob">👂 ${esc(T("只能听：这是 TA 自己那边的事，借过来就不是你的了", "Just for listening — it's about their own life, so it's not one to borrow"))}</div>`;
  const uiM = l === ui ? "" : ZH() ? a.m[1] : TR(a.m[0]); if (uiM && uiM !== strip(a.t)) h += `<div class="ak-mean" dir="auto">${esc(uiM)}</div>`;
