   L:[{en:"It's {ut} in {c}.",zh:"{c}现在{ut}。",es:"En {c} {ut}.",ar:"الساعة في {c} الآن {ut}.",ja:"{c}はいま {ut}。"},{en:"It's {ut} here, and I just {x}.",zh:"我这边{ut}，我刚{x}。",es:"Aquí {ut} y acabo de {x}.",ar:"الساعة هنا {ut}، وقد {x} للتو.",ja:"こっちは {ut}、{x}ところ。"}],
